export CFLAGS="$CFLAGS -fno-sanitize=vptr"
export CXXFLAGS="$CXXFLAGS -fno-sanitize=vptr"
./autogen.sh
./configure --enable-static --disable-shared
make clean
make -j$(nproc) CPPFLAGS="-DHB_NO_VISIBILITY" V=1 all
$CXX $CXXFLAGS -std=c++11 -Isrc     ./test/fuzzing/hb-shape-fuzzer.cc -o $OUT/hb-shape-fuzzer     $LIB_FUZZING_ENGINE ./src/.libs/libharfbuzz.a
$CXX $CXXFLAGS -std=c++11 -Isrc     ./test/fuzzing/hb-draw-fuzzer.cc -o $OUT/hb-draw-fuzzer     $LIB_FUZZING_ENGINE ./src/.libs/libharfbuzz.a
$CXX $CXXFLAGS -std=c++11 -Isrc     ./test/fuzzing/hb-subset-fuzzer.cc -o $OUT/hb-subset-fuzzer     $LIB_FUZZING_ENGINE ./src/.libs/libharfbuzz-subset.a ./src/.libs/libharfbuzz.a
$CXX $CXXFLAGS -std=c++11 -Isrc     ./test/fuzzing/hb-set-fuzzer.cc -o $OUT/hb-set-fuzzer     $LIB_FUZZING_ENGINE ./src/.libs/libharfbuzz.a
mkdir all-fonts
for d in        test/shaping/data/in-house/fonts        test/shaping/data/aots/fonts    test/shaping/data/text-rendering-tests/fonts    test/api/fonts  test/fuzzing/fonts      perf/fonts      ; do
        cp $d/* all-fonts/
done
zip $OUT/hb-shape-fuzzer_seed_corpus.zip all-fonts/*
cp $OUT/hb-shape-fuzzer_seed_corpus.zip $OUT/hb-draw-fuzzer_seed_corpus.zip
cp $OUT/hb-shape-fuzzer_seed_corpus.zip $OUT/hb-subset-fuzzer_seed_corpus.zip
zip $OUT/hb-set-fuzzer_seed_corpus.zip ./test/fuzzing/sets/*
8eba66c1c [gvar] Fix invalid memory access by refactoring GlyphVarData fetch logic
 src/hb-ot-var-gvar-table.hh                                                       |  70 ++++++++++++++++++++++++++++++++++++----------------------------------
 test/fuzzing/fonts/clusterfuzz-testcase-minimized-hb-draw-fuzzer-5088336521986048 | Bin 0 -> 1413 bytes
 2 files changed, 36 insertions(+), 34 deletions(-)
commit 8eba66c1c6d19bcc779a3b4e7b68251511986ee8
Author: Ebrahim Byagowi <ebrahim@gnu.org>
Date:   Thu Feb 27 15:58:58 2020 +0330

    [gvar] Fix invalid memory access by refactoring GlyphVarData fetch logic

    Fixes https://crbug.com/oss-fuzz/20906

diff --git a/src/hb-ot-var-gvar-table.hh b/src/hb-ot-var-gvar-table.hh
index b7d1b5e42..91c2891c3 100644
--- a/src/hb-ot-var-gvar-table.hh
+++ b/src/hb-ot-var-gvar-table.hh
@@ -416,19 +416,25 @@ struct gvar
     unsigned int num_glyphs = c->plan->num_output_glyphs ();
     out->glyphCount = num_glyphs;

+    hb_blob_ptr_t<gvar> table = hb_sanitize_context_t ().reference_table<gvar> (c->plan->source);
+
     unsigned int subset_data_size = 0;
     for (hb_codepoint_t gid = 0; gid < num_glyphs; gid++)
     {
       hb_codepoint_t old_gid;
       if (!c->plan->old_gid_for_new_gid (gid, &old_gid)) continue;
-      subset_data_size += get_glyph_var_data_length (old_gid);
+      subset_data_size += get_glyph_var_data_bytes (table.get_blob (), old_gid).length;
     }

     bool long_offset = subset_data_size & ~0xFFFFu;
     out->flags = long_offset ? 1 : 0;

     HBUINT8 *subset_offsets = c->serializer->allocate_size<HBUINT8> ((long_offset ? 4 : 2) * (num_glyphs + 1));
-    if (!subset_offsets) return_trace (false);
+    if (!subset_offsets)
+    {
+      table.destroy ();
+      return_trace (false);
+    }

     /* shared tuples */
     if (!sharedTupleCount || !sharedTuples)
@@ -437,49 +443,58 @@ struct gvar
     {
       unsigned int shared_tuple_size = F2DOT14::static_size * axisCount * sharedTupleCount;
       F2DOT14 *tuples = c->serializer->allocate_size<F2DOT14> (shared_tuple_size);
-      if (!tuples) return_trace (false);
+      if (!tuples)
+      {
+       table.destroy ();
+       return_trace (false);
+      }
       out->sharedTuples = (char *) tuples - (char *) out;
       memcpy (tuples, &(this+sharedTuples), shared_tuple_size);
     }

     char *subset_data = c->serializer->allocate_size<char> (subset_data_size);
-    if (!subset_data) return_trace (false);
+    if (!subset_data)
+    {
+      table.destroy ();
+      return_trace (false);
+    }
     out->dataZ = subset_data - (char *)out;

     unsigned int glyph_offset = 0;
     for (hb_codepoint_t gid = 0; gid < num_glyphs; gid++)
     {
       hb_codepoint_t old_gid;
-      unsigned int length = c->plan->old_gid_for_new_gid (gid, &old_gid) ? get_glyph_var_data_length (old_gid) : 0;
+      hb_bytes_t var_data_bytes = c->plan->old_gid_for_new_gid (gid, &old_gid)
+                               ? get_glyph_var_data_bytes (table.get_blob (), old_gid)
+                               : hb_bytes_t ();

       if (long_offset)
        ((HBUINT32 *) subset_offsets)[gid] = glyph_offset;
       else
        ((HBUINT16 *) subset_offsets)[gid] = glyph_offset / 2;

-      if (length > 0) memcpy (subset_data, &get_glyph_var_data (old_gid), length);
-      subset_data += length;
-      glyph_offset += length;
+      if (var_data_bytes.length > 0)
+       memcpy (subset_data, var_data_bytes.arrayZ, var_data_bytes.length);
+      subset_data += var_data_bytes.length;
+      glyph_offset += var_data_bytes.length;
     }
     if (long_offset)
       ((HBUINT32 *) subset_offsets)[num_glyphs] = glyph_offset;
     else
       ((HBUINT16 *) subset_offsets)[num_glyphs] = glyph_offset / 2;

+    table.destroy ();
     return_trace (true);
   }

   protected:
-  const GlyphVarData &get_glyph_var_data (hb_codepoint_t glyph) const
+  const hb_bytes_t get_glyph_var_data_bytes (hb_blob_t *blob, hb_codepoint_t glyph) const
   {
-    unsigned int start_offset = get_offset (glyph);
-    unsigned int end_offset = get_offset (glyph+1);
-
-    if ((start_offset == end_offset) ||
-       unlikely ((start_offset > get_offset (glyphCount)) ||
-                 (start_offset + GlyphVarData::min_size > end_offset)))
-      return Null (GlyphVarData);
-    return (((unsigned char *) this + start_offset) + dataZ);
+    unsigned start_offset = get_offset (glyph);
+    unsigned length = get_offset (glyph+1) - start_offset;
+    return unlikely (GlyphVarData::min_size > length)
+        ? hb_bytes_t ()
+        : blob->as_bytes ().sub_array (((unsigned) dataZ) + start_offset, length);
   }

   bool is_long_offset () const { return (flags & 1) != 0; }
@@ -492,15 +507,6 @@ struct gvar
       return get_short_offset_array ()[i] * 2;
   }

-  unsigned int get_glyph_var_data_length (unsigned int glyph) const
-  {
-    unsigned int end_offset = get_offset (glyph + 1);
-    unsigned int start_offset = get_offset (glyph);
-    if (unlikely (start_offset > end_offset || end_offset > get_offset (glyphCount)))
-      return 0;
-    return end_offset - start_offset;
-  }
-
   const HBUINT32 * get_long_offset_array () const { return (const HBUINT32 *) &offsetZ; }
   const HBUINT16 *get_short_offset_array () const { return (const HBUINT16 *) &offsetZ; }

@@ -568,12 +574,12 @@ struct gvar
       coord_count = hb_min (coord_count, gvar_table->axisCount);
       if (!coord_count || coord_count != gvar_table->axisCount) return true;

-      const GlyphVarData &var_data = gvar_table->get_glyph_var_data (glyph);
-      if (!var_data.has_data ()) return true;
+      hb_bytes_t var_data_bytes = gvar_table->get_glyph_var_data_bytes (gvar_table.get_blob (), glyph);
+      const GlyphVarData *var_data = var_data_bytes.as<GlyphVarData> ();
+      if (!var_data->has_data ()) return true;
       hb_vector_t<unsigned int> shared_indices;
       GlyphVarData::tuple_iterator_t iterator;
-      if (!GlyphVarData::get_tuple_iterator (&var_data,
-                                            gvar_table->get_glyph_var_data_length (glyph),
+      if (!GlyphVarData::get_tuple_iterator (var_data, var_data_bytes.length,
                                             gvar_table->axisCount,
                                             shared_indices,
                                             &iterator))
@@ -699,10 +705,6 @@ no_more_gaps:

     unsigned int get_axis_count () const { return gvar_table->axisCount; }

-    protected:
-    const GlyphVarData &get_glyph_var_data (hb_codepoint_t glyph) const
-    { return gvar_table->get_glyph_var_data (glyph); }
-
     private:
     hb_blob_ptr_t<gvar> gvar_table;
     hb_vector_t<F2DOT14> shared_tuples;
1af3363f9 [gvar] Use hb_array_t instead indexing raw pointers
 src/hb-ot-var-gvar-table.hh | 39 ++++++++++++++++++---------------------
 1 file changed, 18 insertions(+), 21 deletions(-)
commit 1af3363f9e4b52d68e6dd5600cef4479614292d5
Author: Ebrahim Byagowi <ebrahim@gnu.org>
Date:   Wed Mar 4 11:32:01 2020 +0330

    [gvar] Use hb_array_t instead indexing raw pointers

diff --git a/src/hb-ot-var-gvar-table.hh b/src/hb-ot-var-gvar-table.hh
index 9cf319a36..034d2193e 100644
--- a/src/hb-ot-var-gvar-table.hh
+++ b/src/hb-ot-var-gvar-table.hh
@@ -95,34 +95,31 @@ struct TuppleIndex : HBUINT16

 struct TupleVarHeader
 {
-  unsigned int get_size (unsigned int axis_count) const
-  {
-    return min_size +
-          (has_peak () ? get_peak_tuple ().get_size (axis_count) : 0) +
-          (has_intermediate () ? (get_start_tuple (axis_count).get_size (axis_count) +
-                                  get_end_tuple (axis_count).get_size (axis_count)) : 0);
-  }
+  unsigned get_size (unsigned axis_count) const
+  { return min_size + get_all_tuples (axis_count).get_size (); }

-  const TupleVarHeader &get_next (unsigned int axis_count) const
+  unsigned get_data_size () const { return varDataSize; }
+
+  const TupleVarHeader &get_next (unsigned axis_count) const
   { return StructAtOffset<TupleVarHeader> (this, get_size (axis_count)); }

   float calculate_scalar (const int *coords, unsigned int coord_count,
                          const hb_array_t<const F2DOT14> shared_tuples) const
   {
-    const F2DOT14 *peak_tuple;
+    hb_array_t<const F2DOT14> peak_tuple;

     if (has_peak ())
-      peak_tuple = &(get_peak_tuple ()[0]);
+      peak_tuple = get_peak_tuple (coord_count);
     else
     {
       unsigned int index = get_index ();
       if (unlikely (index * coord_count >= shared_tuples.length))
        return 0.f;
-      peak_tuple = &shared_tuples[coord_count * index];
+      peak_tuple = shared_tuples.sub_array (coord_count * index, coord_count);
     }

-    const F2DOT14 *start_tuple = nullptr;
-    const F2DOT14 *end_tuple = nullptr;
+    hb_array_t<const F2DOT14> start_tuple;
+    hb_array_t<const F2DOT14> end_tuple;
     if (has_intermediate ())
     {
       start_tuple = get_start_tuple (coord_count);
@@ -155,20 +152,20 @@ struct TupleVarHeader
     return scalar;
   }

-  unsigned int get_data_size () const { return varDataSize; }
-
   bool           has_peak () const { return (tupleIndex & TuppleIndex::EmbeddedPeakTuple); }
   bool   has_intermediate () const { return (tupleIndex & TuppleIndex::IntermediateRegion); }
   bool has_private_points () const { return (tupleIndex & TuppleIndex::PrivatePointNumbers); }
   unsigned int  get_index () const { return (tupleIndex & TuppleIndex::TupleIndexMask); }

   protected:
-  const Tuple &get_peak_tuple () const
-  { return StructAfter<Tuple> (tupleIndex); }
-  const Tuple &get_start_tuple (unsigned int axis_count) const
-  { return *(const Tuple *) &get_peak_tuple ()[has_peak () ? axis_count : 0]; }
-  const Tuple &get_end_tuple (unsigned int axis_count) const
-  { return *(const Tuple *) &get_peak_tuple ()[has_peak () ? (axis_count * 2) : axis_count]; }
+  hb_array_t<const F2DOT14> get_all_tuples (unsigned axis_count) const
+  { return StructAfter<UnsizedArrayOf<F2DOT14>> (tupleIndex).as_array ((has_peak () + has_intermediate () * 2) * axis_count); }
+  hb_array_t<const F2DOT14> get_peak_tuple (unsigned axis_count) const
+  { return get_all_tuples (axis_count).sub_array (0, axis_count); }
+  hb_array_t<const F2DOT14> get_start_tuple (unsigned axis_count) const
+  { return get_all_tuples (axis_count).sub_array (has_peak () * axis_count, axis_count); }
+  hb_array_t<const F2DOT14> get_end_tuple (unsigned axis_count) const
+  { return get_all_tuples (axis_count).sub_array (has_peak () * axis_count + axis_count, axis_count); }

   HBUINT16             varDataSize;
   TuppleIndex          tupleIndex;
